  html=(root/'index.html').read_text().replace('let previous=performance.now();',hook);context.route(base,lambda r:r.fulfill(body=html,content_type='text/html'));page=context.new_page();errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.goto(base);page.wait_for_function('window.__coordsTest',timeout=180000);page.get_by_role('button',name='開始探索',exact=True).click();assert page.locator('#developerCoordinates').is_hidden()
