  assert page.locator('#developerCoordinates').is_visible();page.evaluate('window.__coordsTest.at(-262,-7)');page.wait_for_function("document.getElementById('coordinateValue').textContent.includes('-262.00')");page.get_by_role('button',name='複製座標',exact=True).click();page.wait_for_function('window.__copied');data=page.evaluate('JSON.parse(window.__copied)');assert data['x']==-262 and data['z']==-7 and data['location']=='目前位置',data
  page.evaluate('window.__coordsTest.aerial();window.__coordsTest.pan(-260,-5)');page.wait_for_function("document.getElementById('coordinateValue').textContent.includes('-260.00')");assert '空中觀察中心' in page.locator('#developerCoordinates').inner_text();assert '40.0' in page.locator('#coordinateValue').inner_text();page.locator('#developerCoordinates button').click();page.wait_for_function("JSON.parse(window.__copied).location==='空中觀察中心'");data=page.evaluate('JSON.parse(window.__copied)');assert data['x']==-260 and data['z']==-5 and data['aerialHeight']==40,data
